export async function processRequest(input, ctx) {
  const {
    imagePath,
    prompt = '',
    systemPrompt = '',
  } = input || {};

  if (!imagePath) {
    return {
      status: 'error',
      message: 'imagePath is required',
      input,
      timestamp: new Date().toISOString(),
      output: null,
    };
  }

  const baseUrl = 'https://visionai.maxsolo.co.uk';

  const url = new URL(baseUrl);
  url.searchParams.set('imagePath', String(imagePath));
  url.searchParams.set('prompt', String(prompt));
  url.searchParams.set('systemprompt', String(systemPrompt));

  try {
    const res = await fetch(url.toString());

    if (!res.ok) {
      const text = await res.text();
      console.log('visionai received error body', text);
      return {
        status: 'error',
        message: `visionai error: ${res.status} ${res.statusText}`,
        input,
        timestamp: new Date().toISOString(),
        output: text,
      };
    }

    const visionaiData = await res.json();

    if (ctx && typeof ctx.setVar === 'function') {
      ctx.setVar('visionaiData', visionaiData);
    }

    console.log('visionaiData ok', visionaiData);

    return {
      status: 'success',
      message: 'Request processed',
      input,
      timestamp: new Date().toISOString(),
      output: visionaiData,
    };
  } catch (err) {
    console.log('visionaiData fetch error', err?.message || err);
    return {
      status: 'error',
      message: `Fetch failed: ${err?.message || String(err)}`,
      input,
      timestamp: new Date().toISOString(),
      output: null,
    };
  }
}

