async function processRequest() {
  setVar('DialogueGenerating', true);

  let normalizedPrompt = 'keyword:Operating normally';
  let systemPrompt = 'engineer response';
  const resp = await fetch('https://aichat.maxsolo.co.uk/chat', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ 
      role: 'user', 
