      header.textContent =
        "#" + rank + " - " + (doc.filename || "") +
        " (freq: " + (doc.keyword_freq ?? 0) + ")";
      docBox.appendChild(header);

      if (doc.preview) {
        const previewEl = document.createElement("pre");
        previewEl.textContent = doc.preview;
        docBox.appendChild(previewEl);
      }

      if (doc.file_path) {
        const pathEl = document.createElement("div");
        pathEl.textContent = doc.file_path;
        docBox.appendChild(pathEl);
      }

      container.appendChild(docBox);
    });
  }
}
`;

  return {
    status: "ready",
    clientJS,
  };
}

