// MoveObjectsController
async function processRequest(input) {

  const objects = input.var.objectActions || [];

  const clientJS = `
console.log("MoveObjectsController start");

(function () {
  const configs = ${JSON.stringify(objects || [])};

  if (!Array.isArray(configs) || configs.length === 0) {
    console.warn("MoveObjectsController: no objects");
    return;
  }

  const items = [];

  configs.forEach(cfg => {
    if (!cfg || !cfg.selector) return;
    const el = document.querySelector(cfg.selector);
    if (!el) {
      console.warn("MoveObjectsController: element not found", cfg.selector);
      return;
    }

    const style = window.getComputedStyle(el);
    if (style.position === "static") {
      el.style.position = "absolute";
    }

    const rect = el.getBoundingClientRect();
    const startX = rect.left + window.scrollX;
    const startY = rect.top + window.scrollY;

    const targetX = cfg.targetX ?? startX;
    const targetY = cfg.targetY ?? startY;
    const speed   = cfg.speed   ?? 200;

    items.push({
      el,
      startX,
      startY,
      targetX,
      targetY,
      speed,
      done: false
    });
  });

  if (items.length === 0) {
    console.warn("MoveObjectsController: no valid items");
    return;
  }

  let startTime = null;

  function step(timestamp) {
    if (!startTime) startTime = timestamp;
    const elapsed = (timestamp - startTime) / 1000; // 秒

    let allDone = true;

    items.forEach(item => {
      if (item.done) return;

      const dx = item.targetX - item.startX;
      const dy = item.targetY - item.startY;
      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance === 0) {
        item.done = true;
        return;
      }

      const duration = distance / item.speed; // 秒
      const t = Math.min(elapsed / duration, 1);

      const x = item.startX + dx * t;
      const y = item.startY + dy * t;

      item.el.style.left = x + "px";
      item.el.style.top  = y + "px";

      if (t >= 1) {
        item.done = true;
      } else {
        allDone = false;
      }
    });

    if (!allDone) {
      window.requestAnimationFrame(step);
    }
  }

  window.requestAnimationFrame(step);
})();
`;

  return {
    status: "ready",
    clientJS,
  };
}

