async function processRequest(input) {
    let worlda = getVar("worlda") || [];

    if (!worlda || worlda.length === 0) {
        return {ok: false, error: "No world data found"};
    }

    let worlddata = worlda.find(item => item.id === 'world');
    if (!worlddata || !worlddata.size?.w || !worlddata.size?.h) {
        return {ok: false, error: "Invalid world size"};
    }

    let worldWidth = worlddata.size.w;
    let worldHeight = worlddata.size.h;

    let objectsdata = worlda.filter(item => item.id !== 'world');

    if (objectsdata.length === 0) {
        return {ok: true, message: "No objects to layout"};
    }

    let objectsList = objectsdata.map(o => `${o.id} (${o.name || 'unnamed'})`).join(', ');
    let userPrompt = `World size: ${worldWidth}x${worldHeight}. Objects: ${objectsList}. 
    Assign non-overlapping grid positions (x:0-${worldWidth-1}, y:0-${worldHeight-1}) to each object. 
    Logical layout: machines on edges, players center. 
    Respond ONLY with valid JSON array: [{"id":"obj1","position":{"x":1,"y":2}},{"id":"obj2","position":{"x":3,"y":0}}]`;

    let systemPrompt = 'You are a game level designer. Output only valid JSON array of positions, no other text.';

    try {
        const resp = await fetch('https://aichat.maxsolo.co.uk/api/chat', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ 
                role: 'user', 
                prompt: userPrompt, 
                system: systemPrompt 
            })
        });

        const chatData = await resp.json();
        let aiResponse = chatData.content.trim();

        console.log('AI Layout Response:', aiResponse);

        // Parse JSON (handle minor formatting issues)
        let positions;
        try {
            positions = JSON.parse(aiResponse);
        } catch (e) {
            // Fallback: try extract JSON from text
            let jsonMatch = aiResponse.match(/\[.*\]/s);
            if (jsonMatch) {
                positions = JSON.parse(jsonMatch[0]);
            } else {
                throw e;
            }
        }

        positions.forEach(pos => {
            let obj = objectsdata.find(o => o.id === pos.id);
            if (obj && pos.position) {
                obj.position = { 
                    x: Math.max(0, Math.min(worldWidth - 1, pos.position.x)), 
                    y: Math.max(0, Math.min(worldHeight - 1, pos.position.y)) 
                };
            }
        });

        console.log('AI Positions Applied:', objectsdata.map(o => ({id: o.id, pos: o.position})));

    } catch (error) {
        console.error('AI Layout failed:', error);
        return {ok: false, error: 'AI layout failed, using manual'};
    }

    let updatedWorld = [worlddata, ...objectsdata];
    setVar("worlda", updatedWorld);

    return {
        ok: true,
        updated: objectsdata.length,
        worldSize: {w: worldWidth, h: worldHeight},
        layout: 'AI auto',
        objectsMoved: objectsdata.map(o => ({id: o.id, newPos: o.position}))
    };
}

